#include "study_support.h"
#include <cuda_runtime.h>
#define main ccs_legacy_main
#ifdef CCS_ORIGINAL_REFERENCE
#include "../ccs-cuda/main.cu"
#else
#include "study_corrected_main.cu"
#endif
#undef main
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
template<class T>struct Buf{T*base;T*data;size_t n;T sentinel;Buf(size_t nn,T s):n(nn),sentinel(s){ck(cudaMalloc(&base,(n+16)*sizeof(T)));data=base+8;std::vector<T>v(n+16,s);std::fill(v.begin()+8,v.end()-8,T(0));ck(cudaMemcpy(base,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));}~Buf(){cudaFree(base);}std::vector<T>get(){std::vector<T>v(n);ck(cudaMemcpy(v.data(),data,n*sizeof(T),cudaMemcpyDeviceToHost));return v;}void append(std::vector<double>&v){for(T x:get())v.push_back(x);}void guards(std::vector<double>&v){std::vector<T>g(8);ck(cudaMemcpy(g.data(),base,8*sizeof(T),cudaMemcpyDeviceToHost));for(T x:g)v.push_back(x);ck(cudaMemcpy(g.data(),data+n,8*sizeof(T),cudaMemcpyDeviceToHost));for(T x:g)v.push_back(x);}};
static std::pair<double,std::vector<double>> run(){auto cs=cases();std::vector<double>prefix,out;double sec=0;for(auto&c:cs){Buf<float>gene(c.ng,-777),score(c.m,-777);Buf<int>dc(c.m,-777),sc(c.m,-777);Buf<uint8_t>sample(c.m*c.D,165),data(c.m*c.n,165),tmps(c.m*c.D,165),tmpd(c.m*c.n,165);ck(cudaMemcpy(gene.data,c.gene.data(),c.ng*4,cudaMemcpyHostToDevice));gene.append(prefix);sample.append(prefix);data.append(prefix);score.append(prefix);dc.append(prefix);sc.append(prefix);tmps.append(prefix);tmpd.append(prefix);ck(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(uint32_t rep=0;rep<c.repeat;rep++)compute_bicluster<<<c.m,1>>>(gene.data,c.n,c.m,c.D,c.thr,(char*)sample.data,(char*)data.data,score.data,dc.data,sc.data,(char*)tmps.data,(char*)tmpd.data);ck(cudaDeviceSynchronize());sec+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/c.repeat;sample.append(out);data.append(out);score.append(out);dc.append(out);sc.append(out);tmps.append(out);tmpd.append(out);auto hs=sample.get(),hd=data.get();
#ifdef CCS_ORIGINAL_REFERENCE
hs=tmps.get();hd=tmpd.get();
#endif
auto scores=score.get();auto counts=dc.get(),widths=sc.get();std::vector<bicl>bs(c.m);std::vector<gn>genes(c.n);for(uint32_t i=0;i<c.n;i++){genes[i].x=c.gene.data()+i*(c.D+1);genes[i].indx=i;}for(uint32_t k=0;k<c.m;k++)bs[k]={(char*)hs.data()+k*c.D,(char*)hd.data()+k*c.n,widths[k],counts[k],scores[k]};FILE*f=tmpfile();if(!f)throw std::runtime_error("tmpfile");printbicluster(f,genes.data(),nullptr,c.n,c.D,c.m,c.thr,bs.data(),1,c.overlap);for(uint8_t x:hs)out.push_back(x);for(uint8_t x:hd)out.push_back(x);for(auto&b:bs)out.push_back(b.score);for(auto&b:bs)out.push_back(b.datacount);for(auto&b:bs)out.push_back(b.samplecount);fflush(f);fseek(f,0,SEEK_END);long size=ftell(f);rewind(f);out.push_back(size);for(long i=0;i<size;i++)out.push_back(fgetc(f));fclose(f);if(gene.get()!=c.gene)throw std::runtime_error("genechanged");gene.guards(out);score.guards(out);dc.guards(out);sc.guards(out);sample.guards(out);data.guards(out);tmps.guards(out);tmpd.guards(out);}prefix.insert(prefix.end(),out.begin(),out.end());return {sec,prefix};}
int main(){try{run();for(int trial=1;trial<=5;trial++){auto v=run();std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)v.second.data(),v.second.size()*8);f.close();check(v.second,cases());std::cout<<std::setprecision(17)<<"\nSTUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<v.first<<",\"correct\":true,\"checked_values\":"<<v.second.size()<<",\"max_abs_error\":0,\"max_rel_error\":null,\"timing_region\":\"source_bicluster_kernel_repeat_mean_sum3cases\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"float64\",\"count\":"<<v.second.size()<<",\"byte_order\":\"little\"}}\n";}}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
